  // —— 落地页 · 常见问题 ——
  "landing.faq1.q": "如何注册？",
  "landing.faq1.a":
    "需要邀请码。注册后立即获得 yourname.doulor.cn 子域名、yourname@doulor.cn 邮箱、DNS 管理、临时分享箱与个人名片，这些都不需要额外条件。",
  "landing.faq2.q": "为什么有些模块提示「未向你开放」？",
  "landing.faq2.a":
    "直链网盘、AI 中转站、内网穿透、代理节点这四个模块要消耗真实资源（存储、API 额度、带宽），所以采用「贡献换权限」：提交一份资源、审核通过后自动解锁。同一模块只需贡献一次。",
  "landing.faq3.q": "贡献什么资源？",
  "landing.faq3.a":
    "AI 模型渠道（一个可用的上游 API）、代理订阅链接，或内网穿透的 config.yml。系统会先自动校验连通性与可用性，通过后立即解锁；校验不通过会给出具体原因。",
  "landing.faq4.q": "支持哪些邮件客户端？",
  "landing.faq4.a":
    "收件箱可在网页内直接阅读，也支持转发到你的常用邮箱。AI 中转站解锁后，API Key 兼容主流客户端（如 ChatGPT-Next-Web、LobeChat、OpenAI SDK 等）。",
  "landing.faq5.q": "数据安全如何保障？",
  "landing.faq5.a":
    "所有敏感凭证（Cloudflare Token、第三方凭据）仅存在于 Worker 环境变量，前端不信任任何身份字段，权限一律在服务端校验。用户输入经转义防 XSS。",
  "landing.faq6.q": "架构是什么样的？",
  "landing.faq6.a":
    "纯静态前端 + Cloudflare Workers 后端，数据存 D1，文件存 R2，邮件走 Cloudflare Email Routing。没有自建服务器，全球边缘加速。",
  "landing.faq7.q": "功能会持续扩展吗？",
  "landing.faq7.a":
    "会。目前已覆盖域名、邮箱、网盘、AI、内网穿透、代理节点、临时分享、个人名片等模块，后续会按需增加。",

