  // —— 域名管理 ——
  "dm.title": "域名",
  "dn.terms.title": "域名服务声明与免责条款",
  "dn.terms.intro":
    "本站提供免费的二级子域名注册、DNS 解析及相关管理服务。我们承诺对已注册域名的可用性尽力保证，不会私自注销、删除或修改用户域名（违规处置除外）；但对网络设施故障、上游服务异常、突发故障，以及我们无法控制的政策变动等不在保证范围内。用户需同时遵守下列责任条目，否则此承诺无效。",
  "dn.terms.forbiddenTitle": "禁止内容",
  "dn.terms.forbidden.1": "发布或传播违反所在国家法律法规的信息；",
  "dn.terms.forbidden.2": "搭建钓鱼、木马、色情、赌博等违法违规网站；",
  "dn.terms.forbidden.3": "发送垃圾邮件（SPAM）或进行网络攻击（如 DDoS）；",
  "dn.terms.forbidden.4": "滥用 API、恶意注册或尝试绕过本平台系统限制；",
  "dn.terms.forbidden.5": "部署高风险服务，或可能触发三方平台审查/管控的内容；",
  "dn.terms.forbidden.6": "冒充政府/学校/平台官方等权威机构，或侵犯三方商标/名称权益；",
  "dn.terms.forbidden.7": "恶意占有大量域名而不投入使用，或恶意抢占域名进行倒卖/二次租售。",
  "dn.terms.enforceTitle": "违规处理",
  "dn.terms.enforce":
    "如有违反上述规定，本站有权在不通知的情况下采取包括但不限于警告、封禁账号、冻结域名、删除解析记录等措施，并有义务配合有关部门的调查。",
