  "st.ag.1.title": "一、服务性质",
  "st.ag.1.body": "本模块仅为你提供文件存储与公开直链分享服务。本站不保证存储永久可用、不被删除或数据不丢失，请自行保留重要文件的备份。",
  "st.ag.2.title": "二、禁止存放的内容",
  "st.ag.2.body":
    "严禁上传、存储或分享下列内容：① 儿童色情及任何涉及未成年人的色情内容；② 色情、低俗内容（R18）；③ 恐怖主义、极端暴力、血腥内容；④ 盗版软件、影视、音乐、电子书及其他侵犯他人著作权的资源；⑤ 赌博、诈骗、传销等违法信息；⑥ 恶意软件、木马、病毒、钓鱼页面；⑦ 侵犯他人隐私或含有他人敏感个人信息的内容；⑧ 其他违反中华人民共和国法律法规及你所在地法律的内容。",
  "st.ag.3.title": "三、违规处理",
  "st.ag.3.body":
    "一经发现或经举报核实存在上述内容，本站将立即删除相关文件、停用你的网盘功能，并视情节严重程度对你作出警告、限制功能直至【永久封禁账号】的处理，且不予恢复。构成违法犯罪的，本站将配合有权机关提供必要信息。",
  "st.ag.4.title": "四、你的责任",
  "st.ag.4.body":
    "你须对通过本服务上传、存储、分享的全部内容及由此产生的全部后果独立承担法律责任。因你上传的内容导致本站被第三方索赔、行政处罚或产生其他损失的，你有义务予以赔偿。",
  "st.ag.5.title": "五、直链公开性",
  "st.ag.5.body": "直链是公开的，任何拿到链接的人都能访问。请勿存放隐私文件、证件照、密钥等敏感信息。你应为自己的分享行为负责。",
  "st.ag.6.title": "六、免责与配合",
  "st.ag.6.body": "本站有权在收到有效投诉或依法配合调查时，无需事先通知即删除相关文件并停用账号。管理员有权调整配额、限速或在任何时候关闭整个功能。",
