  "px.probe.hint": "只测订阅地址本身能不能拉到（不测节点）",
  "px.probe.btn": "订阅探活",
  "px.probe.responded": "{name} 响应 {ms} ms",
  "px.probe.unreachable": "订阅地址不可达",
  "px.probe.shortUnreachable": "不可达",
  "px.note":
    "节点的「XX ms」是本站服务器到该节点地址的 TCP 握手耗时（用于分辨死节点与慢节点），不是你在本机用客户端实测的速度，也没有经过节点转发，因此只作参考 —— 以你本地客户端的「延迟测试」为准。QUIC/UDP 协议的节点（hysteria2 / tuic）服务端无法测速。「测不到」只代表本站连不上，不代表节点不可用。剩余流量与到期日以订阅源返回为准。",
  "px.ag.1.title": "一、服务性质",
  "px.ag.1.body": "本模块仅为你提供代理节点订阅链接的浏览与复制服务。节点本身由管理员维护，本站不保证节点随时可用、速度或稳定性。",
  "px.ag.2.title": "二、流量与到期信息",
  "px.ag.2.body": "剩余流量、到期日等信息直接取自订阅源返回的内容，解析不到时显示「未知」。",
  "px.ag.3.title": "三、使用限制",
  "px.ag.3.body": "订阅链接仅限本人使用，不得转赠、转卖或公开传播。你须对使用节点产生的全部行为负责，遵守所在地法律与平台规则。",
  "px.ag.4.title": "四、隐私说明",
  "px.ag.4.body": "启用本功能不会向本站上传你的任何代理流量。访问订阅源时，本站会在服务器端代为抓取并解析，订阅源可能记录访问信息。",
  "px.ag.5.title": "五、免责声明",
  "px.ag.5.body": "因使用代理节点产生的任何直接或间接损失，本站不承担责任。管理员有权在任何时候停用个别节点或整个功能。",
  "px.err.subLink": "获取订阅链接失败",
  "px.err.consentUpdated": "使用协议已更新，请重新阅读并同意",
  "px.err.probe": "检测失败",
  "px.err.speed": "测速失败",
