  "adm.640": "邀请码模块权限",
  "adm.641": "每个模块可设为「基础权限」或「受限模式」。",
  "adm.642": "基础权限：创建邀请码时人人可勾选，不消耗模块额度。",
  "adm.643": "受限模式：需消耗模块额度（捐献获批或手动发放）。",
  "adm.644": "基础权限的模块不消耗额度；受限模块靠捐献或手动发放获取转授额度。",
  "adm.645": "免权限访问",
