  "adm.647": "相当于把该模块对所有人开放。默认全关（按权限卡）。",
  "adm.648": "只旁路「访问时的权限校验」：不会改动任何用户的权限数据，关掉开关即恢复按权限卡。",
  "adm.649": "也不影响各模块自己的「启用」总开关，与上方邀请码权限设置互不相关。",
