  "adm.777": "弹窗提醒登录用户。用户关闭后，「仅一次」不再出现；「每次都弹」时用户可自行选择「不再显示」。",
  "adm.778": "推送到用户邮箱",
  "adm.779": "勾选后，发布/保存时会把这则公告发到所有已验证用户的邮箱。",
  "adm.780": "取消",
  "adm.781": "状态设为「已上线」时立即推送到用户消息中心；设为「定时发布」则到点自动上线。用户点「立即参与」即触发服务端校验与自动发放。",
  "adm.782": "标题",
  "adm.783": "正文（支持 Markdown）",
  "adm.784": "状态",
  "adm.785": "奖励文案（展示用）",
  "adm.786": "定时上线时间",
  "adm.787": "到点后自动上线并推送到用户消息中心。请填未来时间。",
  "adm.788": "奖励类型",
  "adm.789": "抽奖活动的奖励固定是积分（奖池在中奖人数那组配置里填），所以这里锁住不能改。",
  "adm.790": "区间内随机发放",
  "adm.791": "打开后在「下限 ~ 上限」之间随机取一个整数（每个人拿到的数不同，类似抽奖）",
  "adm.792": "积分下限",
  "adm.793": "积分上限",
  "adm.794": "用户未绑定中转站账号时无法自动发放，会落到「待人工发放」，可在领取名单里手动处理。",
  "adm.795": "「积分 → 商城」商品表第一行的内置商品里配置，这里不写死。",
  "adm.796": "与钱包余额不同，积分不要求用户已绑定中转站账号 —— 先攒着，之后由用户",
  "adm.797": "自己在「积分与商城」页兑换成中转站余额或购买商城商品。",
  "adm.798": "区间随机的金额按「活动 + 用户」固定：同一个人重试也拿到同一个数，",
  "adm.799": "不会出现「刷新一下金额变了」。实际发到的数额会记在「领取名单」里。",
  "adm.800": "参与类型",
  "adm.801": "用户必须在活动卡片输入这个码才能领取（不区分大小写）。把码公布在",
  "adm.802": "QQ 群公告等站外位置，即可验证「真的进过群」。码本身不会展示给用户。",
  "adm.803": "用户要填自己的 GitHub 用户名，服务端去这个仓库的 stargazers 名单里核验。",
  "adm.804": "必须是公开仓库",
  "adm.805": "—— 私有仓库读不到名单，会变成「所有人都核验失败」。",
  "adm.806": "点完 star 马上就能领（核验结果按需缓存；「没查到」只缓存 1 分钟，",
  "adm.807": "避免用户点完立刻来领却拿到旧结果）。",
  "adm.808": "还需要给 Worker 配一个 GitHub Token",
  "adm.809": "GitHub 现在要鉴权才肯返回 star 名单，没配的话用户会看到「无法核验」。",
  "adm.810": "中奖人数",
  "adm.811": "奖池积分（总数）",
  "adm.812": "分配方式",
  "adm.813": "平均分（每人一样多）",
  "adm.814": "随机分（有多有少，总数不变）",
  "adm.815": "用户点「参与抽奖」只是报名，当时不发奖。之后两种开奖方式：",
  "adm.816": "你在活动列表点「开奖」立即抽；或到上面填的「结束时间」自动开",
  "adm.817": "（没填结束时间就只会等你手动开）。开奖时从报名者里随机抽，",
  "adm.818": "奖池按分配方式切给中奖者 —— 平均分是每人一样，随机分是各人多少不同但总数不变。",
